 'MMIO, PCI operations, firmware ACK, DMA and Linux RTNL remain inert seams, not hardware or full kernel ABI '
 'execution.',
 'Controller cleanup assumes registered driver actors are retired before MCU queue locks are freed. '
 'Arbitrary raw external queue callers and every concurrent teardown graph are not proved.',
 'Busy bits, PCI clear-master and callback ACK alone do not prove in-flight bus transactions drained. '
